// TableTheme — procedural table themes built from Metal shaders + materials (R-DS-2.1, R-DS-2.2).
//
// A `TableTheme` describes the look of the playing surface — the felt/wood material, its procedural
// color, the rail treatment, and the vignette — as a *pure value*, independent of the system light/dark
// appearance (R-DS-2.2). At least four themes ship: Classic Felt, Midnight, Walnut Parlor, and Minimal
// (R-DS-2.1). The look is generated by Metal shaders through SwiftUI's shader APIs (felt fiber/vignette,
// wood grain, sheen — design.md §6, ADR 0001) driven by these parameters, NOT by large bitmaps.
//
// Why the model is a pure, Foundation-only value:
//   * it is appearance-agnostic by construction — a theme names its own colors, so it never consults the
//     system appearance (R-DS-2.2); switching themes never depends on light/dark chrome, and vice versa;
//   * the whole theme catalog (count, uniqueness, well-formed parameters) is verifiable headless in
//     `swift test` without importing SwiftUI or Metal;
//   * the SwiftUI/Metal bridge that turns these parameters into a rendered surface lives in the UI-only
//     `TableTheme+SwiftUI.swift`, so the shader plumbing is a thin adapter over this data.
//
// The parameters here are exactly the inputs the felt/wood/sheen shaders consume: base + accent colors,
// a fiber/grain scale and strength, a highlight (sheen) strength, and a vignette depth. A theme also
// carries the deep "table ink" used to tint height-scaled piece shadows (see `LiftShadow`).

import Foundation

/// The procedural material a table surface is rendered with (R-DS-2.1). Each case maps to a Metal shader
/// family exposed through SwiftUI's shader APIs (design.md §7 `table.material`; ADR 0001 §3).
public enum TableMaterial: String, Sendable, Hashable, CaseIterable, Codable {
    /// Woven felt with procedural fiber noise and a soft vignette (Classic Felt, Midnight).
    case felt
    /// Polished wood with procedural grain and a directional sheen (Walnut Parlor).
    case wood
    /// A flat, low-noise matte surface — minimal fiber, gentle vignette (Minimal).
    case matte
}

/// The procedural inputs a table-surface shader consumes. All values are normalized and appearance-free;
/// the shader turns them into felt fiber / wood grain / sheen with no bitmap texture (R-DS-2.1).
public struct MaterialParameters: Sendable, Hashable, Codable {
    /// The dominant surface color (e.g. the felt green or the wood mid-tone).
    public let base: TokenColor
    /// A secondary color the shader blends toward for fiber/grain contrast and the rail.
    public let accent: TokenColor
    /// Fiber/grain frequency, in cycles across the surface (higher = finer weave/grain). `> 0`.
    public let grainScale: Double
    /// Fiber/grain contrast strength, 0...1 (0 = flat color, 1 = strongly textured).
    public let grainStrength: Double
    /// Directional sheen/highlight strength, 0...1 (wood polish, felt light response).
    public let sheenStrength: Double
    /// Vignette depth at the edges, 0...1 (0 = none, 1 = strong darkening toward the rail).
    public let vignette: Double

    public init(
        base: TokenColor,
        accent: TokenColor,
        grainScale: Double,
        grainStrength: Double,
        sheenStrength: Double,
        vignette: Double
    ) {
        self.base = base
        self.accent = accent
        self.grainScale = max(0, grainScale)
        self.grainStrength = MaterialParameters.clamp01(grainStrength)
        self.sheenStrength = MaterialParameters.clamp01(sheenStrength)
        self.vignette = MaterialParameters.clamp01(vignette)
    }

    private static func clamp01(_ v: Double) -> Double { min(1, max(0, v)) }
}

/// A complete, appearance-independent table theme (R-DS-2.1, R-DS-2.2).
///
/// A theme is a stable `id` (matching its `Assets/ThemePacks/<id>/` folder), a human-readable
/// `displayName`, the `material` + `parameters` its shader renders from, and the `shadowInk` used to
/// tint the height-scaled shadows cards cast on this surface. Because a theme names all of its own
/// colors, it renders identically regardless of the system light/dark setting (R-DS-2.2).
public struct TableTheme: Sendable, Hashable, Identifiable, Codable {
    /// Stable identifier; also the theme-pack folder name (design.md §7).
    public let id: String
    /// The name shown in Settings.
    public let displayName: String
    /// The procedural material family the surface is drawn with.
    public let material: TableMaterial
    /// The shader inputs for this theme's surface.
    public let parameters: MaterialParameters
    /// The color piece shadows are tinted with on this surface (see `LiftShadow`).
    public let shadowInk: TokenColor

    public init(
        id: String,
        displayName: String,
        material: TableMaterial,
        parameters: MaterialParameters,
        shadowInk: TokenColor
    ) {
        self.id = id
        self.displayName = displayName
        self.material = material
        self.parameters = parameters
        self.shadowInk = shadowInk
    }
}

// MARK: - Built-in themes (≥ 4 — R-DS-2.1)

extension TableTheme {
    /// Classic Felt — a warm, traditional green baize with a fine woven fiber and a soft vignette.
    public static let classicFelt = TableTheme(
        id: "classic-felt",
        displayName: "Classic Felt",
        material: .felt,
        parameters: MaterialParameters(
            base: TokenColor(hex: 0x1B5E20),  // deep baize green
            accent: TokenColor(hex: 0x2E7D32),  // lighter fiber highlight
            grainScale: 220,
            grainStrength: 0.35,
            sheenStrength: 0.12,
            vignette: 0.30
        ),
        shadowInk: TokenColor(hex: 0x06180A)  // very dark green-black
    )

    /// Midnight — a cool, dark blue-green felt for low-light play; deeper vignette, subtle fiber.
    public static let midnight = TableTheme(
        id: "midnight",
        displayName: "Midnight",
        material: .felt,
        parameters: MaterialParameters(
            base: TokenColor(hex: 0x102027),  // near-black blue
            accent: TokenColor(hex: 0x1C3A44),  // muted teal fiber
            grainScale: 200,
            grainStrength: 0.28,
            sheenStrength: 0.10,
            vignette: 0.45
        ),
        shadowInk: TokenColor(hex: 0x02080B)
    )

    /// Walnut Parlor — a polished wood table: warm grain with a directional sheen and a light vignette.
    public static let walnutParlor = TableTheme(
        id: "walnut-parlor",
        displayName: "Walnut Parlor",
        material: .wood,
        parameters: MaterialParameters(
            base: TokenColor(hex: 0x5A3A22),  // walnut mid-tone
            accent: TokenColor(hex: 0x3A2414),  // darker grain lines
            grainScale: 90,
            grainStrength: 0.5,
            sheenStrength: 0.35,
            vignette: 0.25
        ),
        shadowInk: TokenColor(hex: 0x1A0E06)
    )

    /// Minimal — a calm, near-flat matte surface: almost no fiber, a whisper of vignette.
    public static let minimal = TableTheme(
        id: "minimal",
        displayName: "Minimal",
        material: .matte,
        parameters: MaterialParameters(
            base: TokenColor(hex: 0x2B2E33),  // neutral slate
            accent: TokenColor(hex: 0x33373D),
            grainScale: 60,
            grainStrength: 0.06,
            sheenStrength: 0.05,
            vignette: 0.18
        ),
        shadowInk: TokenColor(hex: 0x0B0C0E)
    )

    /// The built-in table themes, in presentation order. At least four ship (R-DS-2.1). Themes are
    /// appearance-independent: this catalog is identical under light and dark system settings (R-DS-2.2).
    public static let all: [TableTheme] = [classicFelt, midnight, walnutParlor, minimal]

    /// Look up a built-in theme by its `id`, or `nil` if none matches.
    public static func theme(id: String) -> TableTheme? {
        all.first { $0.id == id }
    }

    /// The default table theme.
    public static let `default`: TableTheme = .classicFelt
}
